#include "stdafx.h"#include "HcdElementBase.h"struct SDLAY_P{#include "PrivateVars/DLAY.h"};class KDLAY : public KHcdElementBase  , protected SDLAY_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _DLAY("DLAY", KDLAY::Create);IHcdElement *KDLAY::Create(){  return new KDLAY;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KDLAY, 9 )void KDLAY::InitParm(){#include "PrivateVars/DLAY.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KDLAY::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KDLAY::StepCalc( SStepCalcParams &params ){  if( !TimerMode )//ON  {    if( !INPUT )    {      OUT = 0;      TREM = 0;      TELPS = 0;      return;    }    if( TELPS != TSPO )    {      TSPO = TREM = TSPI;      TREM -= params.dtS;      TELPS = params.dtS;      return;    }    TELPS += params.dtS;    TREM -= params.dtS;    if( TELPS >= TSPO )    {      OUT = 1;      TELPS = TSPO;      TREM = 0;    }    return;  }  if( INPUT )  {    OUT = 1;    TREM = 0;    TELPS = 0;    return;  }  if( TELPS != TSPO )  {    TSPO = TREM = TSPI;    TREM -= params.dtS;    TELPS = params.dtS;    return;  }  TELPS += params.dtS;  TREM -= params.dtS;  if( TELPS >= TSPO )  {    OUT = 0;    TELPS = TSPO;    TREM = 0;  }}